<script lang="ts">
 import {DEFAULT_PRODUCT_LAYOUT,type ProductSection} from '../../lib/catalog-presentation';
 let {layout=$bindable<ProductSection[][]>(),lang='en'}=$props<{layout:ProductSection[][];lang?:'en'|'th'}>();
 const names={en:{badge:'Badge',name:'Product name',description:'Description',options:'Options',price:'Price',availability:'Availability',quantity:'Quantity',purchase:'Purchase / contact',reviews:'Customer reviews'},th:{badge:'ป้ายสินค้า',name:'ชื่อสินค้า',description:'คำอธิบาย',options:'ตัวเลือก',price:'ราคา',availability:'สถานะสินค้า',quantity:'จำนวน',purchase:'ซื้อสินค้า / ติดต่อร้าน',reviews:'รีวิวลูกค้า'}};
 function move(index:number,direction:number){const next=layout.map(row=>[...row]),target=index+direction;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];layout=next;}
 function combine(index:number){layout=layout.flatMap((row,i)=>i===index-1?[[...row,...layout[index]]]:i===index?[]:[row]);}
 function preset(value:string){layout=DEFAULT_PRODUCT_LAYOUT.map(row=>[...row]);if(value==='compact')layout=layout.flatMap(row=>row[0]==='availability'?[['availability','quantity'] as ProductSection[]]:row[0]==='quantity'?[]:[row]);}
</script>
<section class="layout-editor"><h2>{lang==='th'?'จัดวางหน้าสินค้า':'Page layout'}</h2><p class="catalog-help">{lang==='th'?'จัดลำดับแยกตามสินค้า หรือรวมสองส่วนในแถวเดียวกัน บนมือถือจะแสดงต่อกันในแนวตั้ง ดูการเปลี่ยนแปลงในตัวอย่างด้านข้าง':'Arrange sections for this product. Combine two sections in one row; they stack on small screens. The preview updates as you edit.'}</p>
 <label>{lang==='th'?'เริ่มจากรูปแบบสำเร็จรูป':'Start from a preset'}<select class="input" value="" onchange={event=>{preset(event.currentTarget.value);event.currentTarget.value='';}}><option value="" disabled>{lang==='th'?'เลือกรูปแบบ…':'Choose a preset…'}</option><option value="standard">{lang==='th'?'มาตรฐาน':'Standard'}</option><option value="compact">{lang==='th'?'กะทัดรัด':'Compact'}</option></select></label>
 <div class="layout-rows">{#each layout as row,index}<div class="layout-row"><div class="layout-labels">{#each row as section}<span>{names[lang][section]}</span>{/each}</div><div class="row"><button type="button" class="btn" aria-label={`${lang==='th'?'เลื่อนขึ้น':'Move up'}: ${row.map(key=>names[lang][key]).join(', ')}`} disabled={index===0} onclick={()=>move(index,-1)}>↑</button><button type="button" class="btn" aria-label={`${lang==='th'?'เลื่อนลง':'Move down'}: ${row.map(key=>names[lang][key]).join(', ')}`} disabled={index===layout.length-1} onclick={()=>move(index,1)}>↓</button>{#if index>0&&row.length+layout[index-1].length<=2}<button type="button" class="btn" onclick={()=>combine(index)}>{lang==='th'?'รวมกับแถวก่อนหน้า':'Combine with previous'}</button>{/if}{#if row.length>1}<button type="button" class="btn" onclick={()=>layout=layout.flatMap((item,i)=>i===index?item.map(section=>[section]):[item])}>{lang==='th'?'แยกแถว':'Split row'}</button>{/if}</div></div>{/each}</div>
</section>
